svg.script:
document.addEventListener("DOMContentLoaded", function() {
  // 类似 Flash SWF 的内嵌动作逻辑：实时监听动画与随机微风互动
  var svg = document.documentElement;
  var snail = document.getElementById("liveSnail");
  if (snail) {
    // 支持点击小蜗牛触发加速爬行趣味交互
    snail.style.cursor = "pointer";
    snail.addEventListener("click", function() {
      snail.style.animationDuration = "12s";
      setTimeout(function() {
        snail.style.animationDuration = "45s";
      }, 6000);
    });
  }
});
